#include "ReviewSession.h"
#include <algorithm>
#include <cmath>
namespace drawborad {
Result<ReviewSession> ReviewSession::create(const ProposalSet&p,const MaskSet&m,Revision r){if(p.candidates.size()!=m.fullResolutionMasks.size())return error(ErrorCode::InvalidInput,"review.mask-count");ReviewSession s;s.proposals_=p;s.masks_=m;s.revision_=r;s.locked_.assign(m.fullResolutionMasks.size(),false);return s;}
Result<void> ReviewSession::apply(const MaskEdit&e){if(e.expectedRevision!=revision_)return error(ErrorCode::StaleRevision,"review.revision");if(e.objectIndex>=masks_.fullResolutionMasks.size())return error(ErrorCode::InvalidInput,"review.object");if(locked_[e.objectIndex]&&e.operation!=MaskEditOp::Unlock)return error(ErrorCode::Locked,"review.mask-locked");undo_.push_back({masks_,locked_});if(e.operation==MaskEditOp::Lock){locked_[e.objectIndex]=true;revision_++;return{};}if(e.operation==MaskEditOp::Unlock){locked_[e.objectIndex]=false;revision_++;return{};}auto& m=masks_.fullResolutionMasks[e.objectIndex];auto w=masks_.dimensions.width,h=masks_.dimensions.height;if(m.size()!=w*h)return error(ErrorCode::CorruptData,"review.mask-layout");auto x0=std::max<std::int64_t>(0,e.region.x),y0=std::max<std::int64_t>(0,e.region.y);auto x1=std::min<std::uint64_t>(w,std::uint64_t(x0)+e.region.width),y1=std::min<std::uint64_t>(h,std::uint64_t(y0)+e.region.height);if(e.operation==MaskEditOp::AddBrush||e.operation==MaskEditOp::SubtractBrush){auto v=e.operation==MaskEditOp::AddBrush?std::uint8_t(255):std::uint8_t(0);for(std::uint64_t y=y0;y<y1;y++)for(std::uint64_t x=x0;x<x1;x++)m[std::size_t(y*w+x)]=v;}else if(e.operation==MaskEditOp::Grow||e.operation==MaskEditOp::Shrink){Bytes before=m;int rad=int(std::clamp(e.radiusPx,1.0,64.0));for(std::uint64_t y=0;y<h;y++)for(std::uint64_t x=0;x<w;x++){bool hit=e.operation==MaskEditOp::Shrink;for(int dy=-rad;dy<=rad;dy++)for(int dx=-rad;dx<=rad;dx++){auto xx=std::int64_t(x)+dx,yy=std::int64_t(y)+dy;if(xx<0||yy<0||xx>=std::int64_t(w)||yy>=std::int64_t(h))continue;auto on=before[std::size_t(yy*w+xx)]>127;if(e.operation==MaskEditOp::Grow)hit=hit||on;else hit=hit&&on;}m[std::size_t(y*w+x)]=hit?255:0;}}else if(e.operation==MaskEditOp::Feather){Bytes before=m;for(std::uint64_t y=0;y<h;y++)for(std::uint64_t x=0;x<w;x++){unsigned sum=0,n=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){auto xx=std::int64_t(x)+dx,yy=std::int64_t(y)+dy;if(xx>=0&&yy>=0&&xx<std::int64_t(w)&&yy<std::int64_t(h)){sum+=before[std::size_t(yy*w+xx)];n++;}}m[std::size_t(y*w+x)]=std::uint8_t(sum/n);}}else return error(ErrorCode::UnsupportedFeature,"review.operation");revision_++;return{};}
Result<void> ReviewSession::undo(){if(undo_.empty())return error(ErrorCode::InvalidInput,"review.undo-empty");masks_=undo_.back().masks;locked_=undo_.back().locked;undo_.pop_back();revision_++;return{};}
Result<ReviewedObjects> ReviewSession::accept(Revision expected)const{if(expected!=revision_)return error(ErrorCode::StaleRevision,"review.accept-revision");return ReviewedObjects{masks_.fullResolutionMasks,revision_,true};}
}
